import java.util.*;
public class TextEditing{
    public static int maxLength(String s){
        String result="";
        boolean inParentheses=false;
        for(int i=0;i<s.length();i++){
            char c=s.charAt(i);
            if(c=='(')
                inParentheses=true;
            else if(c==')'){
                inParentheses=false;
                result+="_";
            }
            if(!inParentheses && c!=')')
                result+=c;
        }
        String[] segments=result.split("_");
        int maxLen=0;
        for(String segment:segments)
            maxLen=Math.max(maxLen, segment.length());
        return maxLen;
    }
    public static int count(String s){
        String[] parts=s.split("_");
        int count=0;
        for(String p:parts)
            if(p.length()!=0)
                count++;
        return count;
    }
    public static int words(String s){
        int totalWords=0;
        StringBuilder temp=new StringBuilder();
        boolean inside=false;
        for(int i=0;i<s.length();i++){
            char c=s.charAt(i);
            if(c=='(')
                inside=true;
            else if(c==')'){
                inside=false;
                totalWords+=count(temp.toString());
                temp.setLength(0);
            }
            if(inside && c!='(')
                temp.append(c);
        }
        return totalWords;
    }
    public static void main(String[] args) {
        Scanner sc=new Scanner(System.in);
        int n=sc.nextInt();
        String s=sc.next();
        System.out.println(maxLength(s)+" "+words(s));
    }
}
